def abc_class(picks):
    """A = top 20% of SKUs by picks, B = next 30%, C = the rest."""
    ranked = picks.rank(pct=True, ascending=False)
    return ranked.map(lambda p: "A" if p <= 0.2 else "B" if p <= 0.5 else "C")

