def assign(skus, slots, score):
    """Best-scoring free slot for each SKU, fastest movers first."""
    free = set(slots)
    result = {}
    for s in skus:
        best = max(free, key=lambda l: score(s, l))
        result[s] = best
        free.remove(best)
    return result

