def occupancy(slots, assignment):
    """Share of slots in use per zone after the proposed moves."""
    used = set(assignment.values())
    totals, busy = {}, {}
    for loc in slots:
        z = loc["zone"]
        totals[z] = totals.get(z, 0) + 1
        busy[z] = busy.get(z, 0) + (loc["code"] in used)
    return {z: busy[z] / totals[z] for z in totals}

